//! SKMEM-R-06C: the reader (audience) ceiling and the query sanitizer.
//!
//! Part 1 (pure): golden parity with Python `resolve_reader` /
//! `ReaderScope.allows` / `sanitize_query` (`tests/golden/reader_parity.json`,
//! generated by `tests/golden/gen_reader_golden.py`), then adversarial checks:
//! widening through a per-call reader, an unknown reader string, a blank or
//! conflicting environment, and a hidden id through every lookup path, which
//! must read exactly like a missing id.
//!
//! Part 2 (feature `pg`, env-gated like `pg_arm.rs`): the same properties on the
//! vector, lexical (`ts_rank` and BM25) and graph arms against a scratch schema
//! of a throwaway Postgres.
#[cfg(feature = "pg")]
mod common;

use serde_json::Value;
use skmem::audience::{AudienceConfig, ReaderScope, READER_ENV};
use skmem::env::Env;
use skmem::flat::Store;
use skmem::index::{Index, SearchFilters};
use skmem::model::{Layer, Memory};
use skmem::query_sanitizer::sanitize_query;
use std::path::{Path, PathBuf};

fn golden() -> Value {
    let p = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/golden/reader_parity.json");
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

fn scope(reader: Option<&str>, env_reader: Option<&str>) -> ReaderScope {
    let env = match env_reader {
        Some(v) => Env::empty().with(READER_ENV, v),
        None => Env::empty(),
    };
    ReaderScope::resolve(reader, &env, &AudienceConfig::empty())
}

fn owner() -> ReaderScope {
    scope(None, None)
}

fn public() -> ReaderScope {
    scope(Some("@public"), None)
}

// ------------------------------------------------------------------ golden

#[test]
fn reader_resolution_matches_python() {
    let g = golden();
    let cfg = AudienceConfig::from_json(&g["config"].to_string());
    let contexts: Vec<Option<String>> = g["contexts"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| c.as_str().map(str::to_string))
        .collect();
    let tagsets: Vec<Vec<String>> = g["tagsets"]
        .as_array()
        .unwrap()
        .iter()
        .map(|t| {
            t.as_array()
                .unwrap()
                .iter()
                .map(|x| x.as_str().unwrap().to_string())
                .collect()
        })
        .collect();
    let readers = g["readers"].as_array().unwrap();
    assert_eq!(readers.len(), 444);
    for case in readers {
        let reader = case["reader"].as_str();
        let env = match case["env"].as_str() {
            Some(v) => Env::empty().with(READER_ENV, v),
            None => Env::empty(),
        };
        let sc = ReaderScope::resolve(reader, &env, &cfg);
        let label = format!("reader={reader:?} env={:?}", case["env"]);
        let want_allowed: Option<Vec<String>> = case["allowed"]
            .as_array()
            .map(|a| a.iter().map(|x| x.as_str().unwrap().to_string()).collect());
        assert_eq!(sc.allowed_tags(), want_allowed, "{label}: allowed tags");
        let want_ex: Vec<String> = case["exclusions"]
            .as_array()
            .unwrap()
            .iter()
            .map(|x| x.as_str().unwrap().to_string())
            .collect();
        assert_eq!(sc.exclusions(), want_ex, "{label}: exclusions");
        assert_eq!(
            sc.unrestricted(),
            case["unrestricted"].as_bool().unwrap(),
            "{label}: unrestricted"
        );
        let bits = case["allows"].as_str().unwrap().as_bytes();
        let mut k = 0;
        for ctx in &contexts {
            for tags in &tagsets {
                let want = bits[k] == b'1';
                assert_eq!(
                    sc.allows(ctx.as_deref(), tags),
                    want,
                    "{label}: allows({ctx:?}, {tags:?})"
                );
                k += 1;
            }
        }
    }
}

#[test]
fn sanitizer_matches_python() {
    let g = golden();
    let cases = g["sanitize"].as_array().unwrap();
    assert_eq!(cases.len(), 41);
    for c in cases {
        let input = c["in"].as_str().unwrap();
        assert_eq!(
            sanitize_query(input),
            c["out"].as_str().unwrap(),
            "sanitize_query({:.60?})",
            input
        );
    }
}

// ------------------------------------------------- scope: widening attempts

#[test]
fn per_call_reader_can_never_widen_the_env_ceiling() {
    for ceiling in ["@public", "@community", "@work:a", "@inner-circle"] {
        let base = scope(None, Some(ceiling));
        let allowed_base = base.allowed_tags().expect("a ceiling is never the owner");
        for attempt in [
            "@chef-only",
            "@chef",
            "owner",
            "OWNER",
            " @Chef-Only ",
            "@inner-circle",
            "@work:b",
            "channel:anything",
            "@unknown",
            "",
        ] {
            let sc = scope(Some(attempt), Some(ceiling));
            let got = sc.allowed_tags().expect("still restricted");
            assert!(
                got.iter().all(|t| allowed_base.contains(t)),
                "reader {attempt:?} under ceiling {ceiling:?} widened to {got:?}"
            );
            assert!(!sc.allows(Some("@chef-only"), &[]));
            assert!(!sc.allows(None, &[]));
        }
    }
}

#[test]
fn conflicting_env_and_call_intersect() {
    // env says @work:a, the call says @work:b: they share only what is below both.
    let sc = scope(Some("@work:b"), Some("@work:a"));
    assert!(!sc.allows(Some("@work:a"), &[]));
    assert!(!sc.allows(Some("@work:b"), &[]));
    assert!(sc.allows(Some("@community"), &[]));
}

#[test]
fn unknown_and_blank_readers_never_widen() {
    for r in [
        "",
        " ",
        "root",
        "*",
        "@everyone",
        "channel:",
        "@work:",
        "\u{0}",
        "@chef-only\u{0}",
    ] {
        let sc = scope(Some(r), None);
        assert!(sc.allows(Some("@public"), &[]), "{r:?}");
        assert!(!sc.allows(Some("@community"), &[]), "{r:?}");
        assert!(!sc.allows(Some("@chef-only"), &[]), "{r:?}");
        assert!(!sc.allows(None, &[]), "{r:?}");
    }
    // a blank env value is not a declaration, a junk one is @public
    assert!(scope(None, Some("  ")).unrestricted());
    let junk = scope(None, Some("bogus"));
    assert!(!junk.allows(Some("@community"), &[]));
}

#[test]
fn no_public_constructor_skips_the_env_ceiling() {
    // The only ways to build a scope go through resolve / from_process, and
    // `resolve` applies the environment even for the owner path.
    let sc = ReaderScope::resolve(
        Some("owner"),
        &Env::empty().with(READER_ENV, "@public"),
        &AudienceConfig::empty(),
    );
    assert!(!sc.unrestricted());
    assert!(!sc.allows(Some("@chef-only"), &[]));
}

// ------------------------------------------------------------- corpus

struct Row {
    id: &'static str,
    ctx: &'static str,
    tags: &'static [&'static str],
}

const ROWS: &[Row] = &[
    Row {
        id: "m-pub",
        ctx: "@public",
        tags: &[],
    },
    Row {
        id: "m-com",
        ctx: "@community",
        tags: &[],
    },
    Row {
        id: "m-wa",
        ctx: "@work:a",
        tags: &[],
    },
    Row {
        id: "m-wb",
        ctx: "@work:b",
        tags: &[],
    },
    Row {
        id: "m-inner",
        ctx: "@inner-circle",
        tags: &[],
    },
    Row {
        id: "m-chef",
        ctx: "@chef-only",
        tags: &[],
    },
    Row {
        id: "m-rom",
        ctx: "@public",
        tags: &["romantic"],
    },
    Row {
        id: "m-none",
        ctx: "",
        tags: &[],
    },
];

fn memory(r: &Row) -> Memory {
    let mut m = Memory::new(
        &format!("amberfox {}", r.id),
        &format!("amberfox river stone body of {}", r.id),
    );
    m.id = r.id.to_string();
    m.context_tag = r.ctx.to_string();
    m.tags = r.tags.iter().map(|t| t.to_string()).collect();
    m
}

fn tmp(tag: &str) -> PathBuf {
    let base = std::env::var_os("SKMEM_TEST_TMP")
        .map(PathBuf::from)
        .unwrap_or_else(std::env::temp_dir);
    let d = base.join(format!("skmem-rs06c-{tag}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&d);
    std::fs::create_dir_all(&d).unwrap();
    d
}

fn seeded_store(tag: &str) -> (Store, PathBuf) {
    let dir = tmp(tag);
    let store = Store::open(dir.join("m")).unwrap();
    for r in ROWS {
        store.save(&memory(r)).unwrap();
    }
    (store, dir)
}

fn ids(v: impl IntoIterator<Item = String>) -> Vec<String> {
    let mut v: Vec<String> = v.into_iter().collect();
    v.sort();
    v
}

// ------------------------------------------------- flat store lookup paths

#[test]
fn flat_hidden_id_reads_exactly_like_a_missing_id() {
    let (store, dir) = seeded_store("flat");
    let p = public();
    for hidden in ["m-com", "m-wa", "m-inner", "m-chef", "m-none"] {
        let a = store.load(hidden, &p).unwrap();
        let b = store.load("never-existed", &p).unwrap();
        assert_eq!(a, b, "{hidden}");
        assert!(a.is_none());
        // the owner still sees it
        assert!(store.load(hidden, &owner()).unwrap().is_some());
    }
    assert!(store.load("m-pub", &p).unwrap().is_some());
    // a hostile id is a BadId for everyone, hidden or not (not an oracle)
    assert!(store.load("../m-chef", &p).is_err() == store.load("../m-chef", &owner()).is_err());

    let listed = ids(store.list(None, &p).memories.into_iter().map(|m| m.id));
    assert_eq!(listed, ["m-pub", "m-rom"]);
    let set: Vec<String> = store.flat_id_set(&p).into_iter().collect();
    assert_eq!(set, ["m-pub", "m-rom"]);
    assert_eq!(store.flat_id_set(&owner()).len(), ROWS.len());

    // never-share tag: public context, but the channel excludes the tag
    let cfg = AudienceConfig::from_json(
        r#"{"channels":{"c":{"context_tag":"@public","members":["A"]}},
            "people":{"A":{"trust_level":1,"never_share":["romantic"]}}}"#,
    );
    let ch = ReaderScope::resolve(Some("channel:c"), &Env::empty(), &cfg);
    assert!(store.load("m-rom", &ch).unwrap().is_none());
    assert!(store.load("m-pub", &ch).unwrap().is_some());
    assert!(store.load("m-com", &ch).unwrap().is_some());

    std::fs::remove_dir_all(dir).unwrap();
}

#[test]
fn flat_unreadable_file_is_not_an_existence_oracle_for_a_reader() {
    let (store, dir) = seeded_store("flatbad");
    std::fs::write(
        store.layer_dir(Layer::Short).join("broken.json"),
        b"{not json",
    )
    .unwrap();
    // owner: the error is reported. restricted reader: indistinguishable from missing.
    assert!(store.load("broken", &owner()).is_err());
    assert_eq!(
        store.load("broken", &public()).unwrap(),
        store.load("missing", &public()).unwrap()
    );
    let l = store.list(None, &public());
    assert!(
        l.unloadable.is_empty(),
        "a broken file must not be counted for a reader"
    );
    assert!(!store.list(None, &owner()).unloadable.is_empty());
    assert!(!store.flat_id_set(&public()).contains("broken"));
    std::fs::remove_dir_all(dir).unwrap();
}

// ------------------------------------------------------------ index paths

fn seeded_index(tag: &str, fts: bool) -> (Index, PathBuf) {
    let (store, dir) = seeded_store(tag);
    let idx = Index::open(store.root(), fts).unwrap();
    for r in ROWS {
        let m = memory(r);
        idx.index_memory(&m, &store.path_for(&m).unwrap()).unwrap();
    }
    (idx, dir)
}

#[test]
fn index_hidden_id_reads_like_missing_on_get_all_rows_and_search() {
    let (idx, dir) = seeded_index("idx", true);
    let p = public();
    for hidden in ["m-com", "m-wa", "m-inner", "m-chef", "m-none"] {
        assert_eq!(
            idx.get(hidden, &p).unwrap(),
            idx.get("never-existed", &p).unwrap()
        );
        assert!(idx.get(hidden, &p).unwrap().is_none(), "{hidden}");
        assert!(idx.get(hidden, &owner()).unwrap().is_some());
    }
    assert!(idx.get("m-pub", &p).unwrap().is_some());
    assert_eq!(
        ids(idx.all_rows(&p).unwrap().into_iter().map(|r| r.id)),
        ["m-pub", "m-rom"]
    );
    assert_eq!(idx.all_rows(&owner()).unwrap().len(), ROWS.len());

    let all = |sc: &ReaderScope, f: &SearchFilters<'_>| {
        ids(idx
            .search_lexical("amberfox", 50, f, sc)
            .unwrap()
            .into_iter()
            .map(|r| r.id))
    };
    assert_eq!(all(&p, &SearchFilters::default()), ["m-pub", "m-rom"]);
    assert_eq!(all(&owner(), &SearchFilters::default()).len(), ROWS.len());

    // an explicit caller filter can only narrow, never widen, the ceiling
    let want = vec!["@chef-only".to_string(), "@public".to_string()];
    let f = SearchFilters {
        context_tags: Some(&want),
        ..SearchFilters::default()
    };
    assert_eq!(all(&p, &f), ["m-pub", "m-rom"]);
    let only_chef = vec!["@chef-only".to_string()];
    let f2 = SearchFilters {
        context_tags: Some(&only_chef),
        ..SearchFilters::default()
    };
    assert!(all(&p, &f2).is_empty());

    // the hidden rows do not eat the LIMIT: ask for 1 and still get the visible one
    let one = idx
        .search_lexical("amberfox", 1, &SearchFilters::default(), &p)
        .unwrap();
    assert_eq!(one.len(), 1);
    assert!(["m-pub", "m-rom"].contains(&one[0].id.as_str()));

    // widening attempt through the per-call reader under an env ceiling
    let widened = scope(Some("owner"), Some("@public"));
    assert_eq!(all(&widened, &SearchFilters::default()), ["m-pub", "m-rom"]);
    assert!(idx.get("m-chef", &widened).unwrap().is_none());

    // never-share tags
    let cfg = AudienceConfig::from_json(
        r#"{"channels":{"c":{"context_tag":"@public","members":["A"]}},
            "people":{"A":{"trust_level":1,"never_share":["romantic"]}}}"#,
    );
    let ch = ReaderScope::resolve(Some("channel:c"), &Env::empty(), &cfg);
    let seen = all(&ch, &SearchFilters::default());
    assert!(seen.contains(&"m-pub".to_string()) && seen.contains(&"m-com".to_string()));
    assert!(!seen.contains(&"m-rom".to_string()));
    assert!(idx.get("m-rom", &ch).unwrap().is_none());
    std::fs::remove_dir_all(dir).unwrap();
}

#[test]
fn index_without_fts_fails_closed_for_a_reader() {
    // The context tag lives in fts_meta; with FTS off a restricted reader
    // cannot be answered, so it gets nothing (never everything).
    let (idx, dir) = seeded_index("idxnofts", false);
    assert!(idx.get("m-pub", &public()).unwrap().is_none());
    assert!(idx.all_rows(&public()).unwrap().is_empty());
    assert_eq!(idx.all_rows(&owner()).unwrap().len(), ROWS.len());
    std::fs::remove_dir_all(dir).unwrap();
}

// ----------------------------------------------- search::search (fusion)

mod fused {
    use super::*;
    use skmem::fusion::{run_arm, ArmInput};
    use skmem::pytime::Dt;
    use skmem::search::{search, Candidate, SearchInput};
    use std::collections::HashMap;

    fn cand(id: &str, ctx: &str, tags: &[&str]) -> Candidate {
        Candidate {
            id: id.into(),
            title: id.into(),
            content: "amberfox".into(),
            created_at: Some("2026-10-01T00:00:00+00:00".into()),
            layer: "short-term".into(),
            kind: "fact".into(),
            source: "manual".into(),
            source_tier: Some("user-stated".into()),
            schema_version: 2,
            context_tag: ctx.into(),
            tags: tags.iter().map(|t| t.to_string()).collect(),
            ..Candidate::default()
        }
    }

    fn run(
        scope: &ReaderScope,
        arm_ids: &[&str],
        found: &HashMap<String, Candidate>,
    ) -> Option<Vec<String>> {
        let arms = vec![
            run_arm(
                "lexical_local",
                ArmInput::Ids(arm_ids.iter().map(|s| s.to_string()).collect()),
                25,
            ),
            run_arm(
                "vector",
                ArmInput::Ids(arm_ids.iter().rev().map(|s| s.to_string()).collect()),
                25,
            ),
        ];
        let input = SearchInput {
            query: "amberfox",
            scope,
            limit: 10,
            arms: &arms,
            found,
            has_pg_bm25: false,
            df: None,
            usage: None,
            decay_as_of: Dt::parse("2026-11-01T00:00:00+00:00").unwrap(),
        };
        search(&input, &Env::empty()).map(|t| {
            let mut all = t.fused.clone();
            all.extend(t.reranked);
            all.extend(t.demoted);
            all.extend(t.decayed);
            all.extend(t.page);
            all
        })
    }

    fn found_of(cs: Vec<Candidate>) -> HashMap<String, Candidate> {
        cs.into_iter().map(|c| (c.id.clone(), c)).collect()
    }

    #[test]
    fn hidden_candidates_never_appear_in_any_stage() {
        let found = found_of(vec![
            cand("a-pub", "@public", &[]),
            cand("b-chef", "@chef-only", &[]),
            cand("c-pub", "@public", &[]),
            cand("d-wa", "@work:a", &[]),
            cand("e-notag", "", &[]),
        ]);
        let all = ["b-chef", "a-pub", "d-wa", "c-pub", "e-notag", "ghost"];
        let got = run(&public(), &all, &found).unwrap();
        for hidden in ["b-chef", "d-wa", "e-notag", "ghost"] {
            assert!(
                !got.iter().any(|i| i == hidden),
                "{hidden} leaked into {got:?}"
            );
        }
        assert!(got.iter().any(|i| i == "a-pub"));
        // owner keeps the old behaviour (hydrated candidates survive)
        let own = run(&owner(), &all, &found).unwrap();
        assert!(own.iter().any(|i| i == "b-chef"));
    }

    #[test]
    fn hidden_ids_do_not_shift_visible_ranks() {
        // Same visible candidates, with and without hidden ones in the arms:
        // the reader's page must be identical (no rank side channel).
        let vis = [cand("a-pub", "@public", &[]), cand("c-pub", "@public", &[])];
        let mut with_hidden = vec![
            cand("b-chef", "@chef-only", &[]),
            cand("z-chef", "@chef-only", &[]),
        ];
        with_hidden.extend(vis.iter().cloned());
        let page_with = run(
            &public(),
            &["b-chef", "a-pub", "z-chef", "c-pub"],
            &found_of(with_hidden),
        )
        .unwrap();
        let page_without = run(&public(), &["a-pub", "c-pub"], &found_of(vis.to_vec())).unwrap();
        assert_eq!(page_with, page_without);
    }

    #[test]
    fn never_share_tags_are_enforced_on_candidates() {
        let cfg = AudienceConfig::from_json(
            r#"{"channels":{"c":{"context_tag":"@public","members":["A"]}},
                "people":{"A":{"trust_level":1,"never_share":["romantic"]}}}"#,
        );
        let ch = ReaderScope::resolve(Some("channel:c"), &Env::empty(), &cfg);
        let found = found_of(vec![
            cand("ok", "@public", &["x"]),
            cand("rom", "@public", &["romantic"]),
        ]);
        let got = run(&ch, &["rom", "ok"], &found).unwrap();
        assert!(got.iter().any(|i| i == "ok") && !got.iter().any(|i| i == "rom"));
    }

    #[test]
    fn everything_hidden_is_none_like_nothing_found() {
        let found = found_of(vec![cand("b-chef", "@chef-only", &[])]);
        assert_eq!(run(&public(), &["b-chef"], &found), None);
        assert_eq!(run(&public(), &[], &found), None);
    }

    #[test]
    fn the_query_is_sanitized_inside_search() {
        // A polluted query must route like its sanitized tail would.
        let found = found_of(vec![cand("a-pub", "@public", &[])]);
        let arms = vec![run_arm(
            "lexical_local",
            ArmInput::Ids(vec!["a-pub".into()]),
            25,
        )];
        let polluted = format!("You are a bot.\n{}\nwhere is amberfox?", "pad ".repeat(100));
        let own = owner();
        let mk = |q: &'static str| SearchInput {
            query: q,
            scope: &own,
            limit: 5,
            arms: &arms,
            found: &found,
            has_pg_bm25: false,
            df: None,
            usage: None,
            decay_as_of: Dt::parse("2026-11-01T00:00:00+00:00").unwrap(),
        };
        let polluted: &'static str = Box::leak(polluted.into_boxed_str());
        let a = search(&mk(polluted), &Env::empty()).unwrap();
        let b = search(&mk("where is amberfox?"), &Env::empty()).unwrap();
        assert_eq!(a.route, b.route);
        assert_eq!(a.page, b.page);
    }
}

// ================================================================== PG
#[cfg(feature = "pg")]
mod pg {
    use super::*;
    use postgres::{Client, NoTls};
    use serde_json::json;
    use skmem::embed::{EmbedClient, EmbedConfig};
    use skmem::pg::graph_arm::GraphArm;
    use skmem::pg::lexical_arm::LexicalArm;
    use skmem::pg::{ContextTag, Filters, VectorArm};

    use super::common::{det_embed, serve, Reply};

    fn test_dsn() -> Option<String> {
        let Some(dsn) = std::env::var("SKMEM_PG_TEST_DSN")
            .ok()
            .filter(|d| !d.is_empty())
        else {
            eprintln!("SKIP: SKMEM_PG_TEST_DSN not set (needs a loopback Postgres with pgvector)");
            return None;
        };
        let cfg: postgres::Config = dsn.parse().expect("SKMEM_PG_TEST_DSN does not parse");
        for h in cfg.get_hosts() {
            if let postgres::config::Host::Tcp(t) = h {
                assert!(
                    ["127.0.0.1", "localhost", "::1"].contains(&t.as_str()),
                    "SKMEM_PG_TEST_DSN must be loopback"
                );
            }
        }
        Some(dsn)
    }

    const DDL: &str = "CREATE TABLE {s}.memories (
      id text NOT NULL PRIMARY KEY, layer text, role text, title text, content text, summary text,
      tags text[] DEFAULT '{}'::text[], source text,
      created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now(),
      memory_json jsonb NOT NULL, agent text DEFAULT 'lumina', embedding public.vector(1024),
      tsv tsvector GENERATED ALWAYS AS (to_tsvector('english'::regconfig,
        ((((COALESCE(title, ''::text) || ' '::text) || COALESCE(content, ''::text)) || ' '::text)
         || COALESCE(summary, ''::text)))) STORED);
    CREATE INDEX ON {s}.memories USING gin (tsv);";

    const BM25_INDEX: &str = "CREATE INDEX memories_bm25 ON {s}.memories USING bm25 (id, title, content, summary) WITH (key_field=id, text_fields='{
      \"title\":   {\"tokenizer\": {\"type\": \"default\", \"stemmer\": \"English\", \"stopwords_language\": \"English\"}},
      \"content\": {\"tokenizer\": {\"type\": \"default\", \"stemmer\": \"English\", \"stopwords_language\": \"English\"}},
      \"summary\": {\"tokenizer\": {\"type\": \"default\", \"stemmer\": \"English\", \"stopwords_language\": \"English\"}}}');";

    const AGENT: &str = "skrs-06c";

    fn with_schema(dsn: &str, f: impl FnOnce(&str, &str, &mut Client)) {
        static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
        let n = N.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
        let schema = format!("skrs_r06c_{}_{n}", std::process::id());
        let mut c = Client::connect(dsn, NoTls).unwrap();
        c.batch_execute(
            "SELECT pg_advisory_xact_lock(5304); CREATE EXTENSION IF NOT EXISTS vector",
        )
        .unwrap();
        c.batch_execute(&format!(
            "DROP SCHEMA IF EXISTS {schema} CASCADE; CREATE SCHEMA {schema}"
        ))
        .unwrap();
        c.batch_execute(&DDL.replace("{s}", &schema)).unwrap();
        let path = format!("{schema}, public");
        let r =
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| f(&schema, &path, &mut c)));
        let _ = c.batch_execute(&format!("DROP SCHEMA {schema} CASCADE"));
        if let Err(e) = r {
            std::panic::resume_unwind(e);
        }
    }

    /// Seed `ROWS` plus a second agent's copy of a hidden row (agent isolation).
    fn seed(c: &mut Client, schema: &str) {
        for r in ROWS {
            let m = memory(r);
            let emb = pgvector::Vector::from(det_embed(&skmem::embed::embed_text(
                &m.title, &m.content, &m.summary,
            )));
            let mj: Value = serde_json::from_str(&m.to_json()).unwrap();
            c.execute(
                &format!(
                    "INSERT INTO {schema}.memories (id, agent, layer, role, title, content, summary, tags, source, memory_json, embedding) \
                     VALUES ($1,$2,'short-term','user',$3,$4,$5,$6,'manual',$7,$8)"
                ),
                &[&m.id, &AGENT, &m.title, &m.content, &m.summary, &m.tags, &mj, &emb],
            )
            .unwrap();
        }
    }

    fn session(dsn: &str, path: &str) -> Client {
        let mut c = Client::connect(dsn, NoTls).unwrap();
        c.batch_execute(&format!("SET search_path = {path}"))
            .unwrap();
        c
    }

    fn vec_arm(dsn: &str, path: &str) -> (VectorArm, std::sync::Arc<std::sync::Mutex<Vec<usize>>>) {
        let (url, log) = serve(Reply::Ok);
        let e = Box::new(EmbedClient::new(EmbedConfig {
            urls: vec![url],
            ..EmbedConfig::default()
        }));
        (
            VectorArm::from_client(session(dsn, path), AGENT, e).unwrap(),
            log,
        )
    }

    fn all_ids(ids_: Vec<String>) -> Vec<String> {
        ids(ids_)
    }

    #[test]
    fn vector_arm_is_filtered_in_sql_and_hidden_ids_never_return() {
        let Some(dsn) = test_dsn() else { return };
        with_schema(&dsn, |schema, path, c| {
            seed(c, schema);
            let (mut arm, log) = vec_arm(&dsn, path);
            let q = "amberfox river stone";
            let run = |arm: &mut VectorArm, sc: &ReaderScope, limit: i64, f: &Filters| {
                arm.search_semantic(q, limit, f, sc)
                    .unwrap()
                    .into_iter()
                    .map(|h| h.memory.id)
                    .collect::<Vec<_>>()
            };
            let f = Filters::default();
            assert_eq!(run(&mut arm, &owner(), 50, &f).len(), ROWS.len());
            assert_eq!(
                all_ids(run(&mut arm, &public(), 50, &f)),
                ["m-pub", "m-rom"]
            );
            // push-down: LIMIT 1 over a corpus where hidden rows rank equally still
            // returns the visible row (a post-filter would return nothing half the time)
            for _ in 0..3 {
                assert_eq!(run(&mut arm, &public(), 1, &f).len(), 1);
            }
            // widening: per-call owner under an env ceiling, and a caller context filter
            let widened = scope(Some("owner"), Some("@public"));
            assert_eq!(all_ids(run(&mut arm, &widened, 50, &f)), ["m-pub", "m-rom"]);
            let want = Filters {
                context_tag: Some(ContextTag::AnyOf(vec![
                    "@chef-only".into(),
                    "@public".into(),
                ])),
                ..Filters::default()
            };
            assert_eq!(
                all_ids(run(&mut arm, &public(), 50, &want)),
                ["m-pub", "m-rom"]
            );
            let one = Filters {
                context_tag: Some(ContextTag::One("@chef-only".into())),
                ..Filters::default()
            };
            assert!(run(&mut arm, &public(), 50, &one).is_empty());
            // a scoped reader sees its own client tag and the levels below it
            let wa = scope(Some("@work:a"), None);
            assert_eq!(
                all_ids(run(&mut arm, &wa, 50, &f)),
                ["m-com", "m-pub", "m-rom", "m-wa"]
            );
            // never-share tags in SQL
            let cfg = AudienceConfig::from_json(
                r#"{"channels":{"c":{"context_tag":"@public","members":["A"]}},
                    "people":{"A":{"trust_level":1,"never_share":["romantic"]}}}"#,
            );
            let ch = ReaderScope::resolve(Some("channel:c"), &Env::empty(), &cfg);
            assert_eq!(all_ids(run(&mut arm, &ch, 50, &f)), ["m-com", "m-pub"]);
            // the same row is an unknown id for a hidden reader: no error, no hit
            assert!(arm
                .search_vector(det_embed("amberfox m-chef"), 50, &f, &public())
                .unwrap()
                .iter()
                .all(|h| h.memory.id != "m-chef"));
            // the query is sanitized before it is embedded: 5000 chars in, <= 500 out
            let polluted = format!("You are a bot.\n{}\nwhat is amberfox?", "pad ".repeat(1200));
            arm.search_semantic(&polluted, 5, &f, &public()).unwrap();
            let sent = *log.lock().unwrap().last().unwrap();
            assert!(sent <= 500, "embedded {sent} chars");
        });
    }

    fn lex_arm(dsn: &str, path: &str, pin_tsrank: bool) -> LexicalArm {
        let mut a = LexicalArm::from_client(session(dsn, path), AGENT);
        if pin_tsrank {
            a.set_bm25(Some(false));
        }
        a
    }

    fn lex_checks(arm: &mut LexicalArm) {
        let f = Filters::default();
        let run = |arm: &mut LexicalArm, sc: &ReaderScope, limit: i64, f: &Filters| {
            arm.search_lexical("amberfox", limit, f, sc)
                .unwrap()
                .into_iter()
                .map(|h| h.memory.id)
                .collect::<Vec<_>>()
        };
        assert_eq!(run(arm, &owner(), 50, &f).len(), ROWS.len());
        assert_eq!(all_ids(run(arm, &public(), 50, &f)), ["m-pub", "m-rom"]);
        assert_eq!(run(arm, &public(), 1, &f).len(), 1);
        let widened = scope(Some("owner"), Some("@public"));
        assert_eq!(all_ids(run(arm, &widened, 50, &f)), ["m-pub", "m-rom"]);
        let one = Filters {
            context_tag: Some(ContextTag::One("@chef-only".into())),
            ..Filters::default()
        };
        assert!(run(arm, &public(), 50, &one).is_empty());
        let wb = scope(Some("@work:b"), None);
        let got = all_ids(run(arm, &wb, 50, &f));
        assert!(got.contains(&"m-wb".to_string()) && !got.contains(&"m-wa".to_string()));
        let cfg = AudienceConfig::from_json(
            r#"{"channels":{"c":{"context_tag":"@public","members":["A"]}},
                "people":{"A":{"trust_level":1,"never_share":["romantic"]}}}"#,
        );
        let ch = ReaderScope::resolve(Some("channel:c"), &Env::empty(), &cfg);
        assert_eq!(all_ids(run(arm, &ch, 50, &f)), ["m-com", "m-pub"]);
    }

    #[test]
    fn lexical_arm_tsrank_is_filtered_in_sql() {
        let Some(dsn) = test_dsn() else { return };
        with_schema(&dsn, |schema, path, c| {
            seed(c, schema);
            let mut arm = lex_arm(&dsn, path, true);
            lex_checks(&mut arm);
        });
    }

    #[test]
    fn lexical_arm_bm25_is_filtered_in_sql() {
        let Some(dsn) = test_dsn() else { return };
        with_schema(&dsn, |schema, path, c| {
            if let Err(e) = c
                .batch_execute(
                    "SELECT pg_advisory_xact_lock(5305); CREATE EXTENSION IF NOT EXISTS pg_search",
                )
                .and_then(|_| c.batch_execute(&BM25_INDEX.replace("{s}", schema)))
            {
                assert!(
                    std::env::var("SKMEM_PG_TEST_BM25").ok().as_deref() != Some("1"),
                    "SKMEM_PG_TEST_BM25=1 but pg_search is unusable: {e}"
                );
                eprintln!("SKIP: pg_search is not usable on this server");
                return;
            }
            seed(c, schema);
            c.batch_execute(&format!("REINDEX INDEX {schema}.memories_bm25"))
                .unwrap();
            let mut arm = lex_arm(&dsn, path, false);
            lex_checks(&mut arm);
            assert_eq!(
                arm.last_run(),
                Some(&skmem::pg::lexical_arm::LexicalPath::Bm25)
            );
        });
    }

    // ------------------------------------------------------------- graph

    fn has_age(dsn: &str) -> bool {
        let mut c = Client::connect(dsn, NoTls).unwrap();
        let n: i64 = c
            .query_one(
                "SELECT count(*) FROM pg_available_extensions WHERE name = 'age'",
                &[],
            )
            .unwrap()
            .get(0);
        n > 0
    }

    /// Nodes g1..g5 with audiences, entity `Zed` mentioned by all, a chain
    /// g1 <-SUPERSEDES- g2 <-SUPERSEDES- g3 <-SUPERSEDES- g4, g1 RELATED_TO g5.
    /// g3 is `@chef-only`: hidden from a public reader, and it sits in the MIDDLE
    /// of the chain, so lineage must be cut there.
    const G: &[(&str, &str)] = &[
        ("g1", "@public"),
        ("g2", "@public"),
        ("g3", "@chef-only"),
        ("g4", "@public"),
        ("g5", "@community"),
    ];

    fn with_graph(dsn: &str, f: impl FnOnce(&mut GraphArm)) {
        if !has_age(dsn) {
            assert!(
                std::env::var("SKMEM_PG_TEST_AGE").ok().as_deref() != Some("1"),
                "SKMEM_PG_TEST_AGE=1 but the age extension is not available"
            );
            eprintln!("SKIP: the age extension is not available on this server");
            return;
        }
        with_schema(dsn, |schema, path, c| {
            // memories rows (the authoritative audience) for the graph nodes
            for (id, ctx) in G {
                let mut m = Memory::new(&format!("node {id}"), "graph body");
                m.id = id.to_string();
                m.context_tag = ctx.to_string();
                let mj: Value = serde_json::from_str(&m.to_json()).unwrap();
                c.execute(
                    &format!(
                        "INSERT INTO {schema}.memories (id, agent, layer, role, title, content, summary, tags, source, memory_json) \
                         VALUES ($1,$2,'short-term','user',$3,$4,'', '{{}}','manual',$5)"
                    ),
                    &[&m.id, &AGENT, &m.title, &m.content, &mj],
                )
                .unwrap();
            }
            static N: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
            let n = N.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            let graph = format!("skrs_r06cg_{}_{n}", std::process::id());
            let mut admin = Client::connect(dsn, NoTls).unwrap();
            admin
                .batch_execute(
                    "SELECT pg_advisory_xact_lock(5305); CREATE EXTENSION IF NOT EXISTS age",
                )
                .unwrap();
            admin
                .batch_execute("LOAD 'age'; SET search_path = ag_catalog, \"$user\", public")
                .unwrap();
            let _ = admin.query("SELECT ag_catalog.drop_graph($1, true)", &[&graph]);
            admin
                .query("SELECT ag_catalog.create_graph($1)", &[&graph])
                .unwrap();
            let mut arm = GraphArm::from_client(session(dsn, path), AGENT, Some(&graph), true);
            let r = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                for (id, _) in G {
                    arm.cypher(
                        "CREATE (m:Memory {id: $id, title: $t, layer: 'short-term', created_at: '2026-10-01T00:00:00+00:00'}) \
                         MERGE (e:Entity {name: 'Zed'}) CREATE (m)-[:MENTIONS]->(e) RETURN m",
                        &json!({"id": id, "t": format!("node {id}")}),
                        1,
                        None,
                    )
                    .unwrap();
                }
                for (a, b, rel) in [
                    ("g2", "g1", "SUPERSEDES"),
                    ("g3", "g2", "SUPERSEDES"),
                    ("g4", "g3", "SUPERSEDES"),
                    ("g1", "g5", "RELATED_TO"),
                    ("g2", "g3", "RELATED_TO"),
                ] {
                    arm.cypher(
                        &format!(
                            "MATCH (a:Memory {{id: $a}}), (b:Memory {{id: $b}}) \
                             CREATE (a)-[e:{rel}]->(b) SET e.valid_from = '2026-01-01T00:00:00+00:00' RETURN b"
                        ),
                        &json!({"a": a, "b": b}),
                        1,
                        None,
                    )
                    .unwrap();
                }
                f(&mut arm)
            }));
            let _ = admin.query("SELECT ag_catalog.drop_graph($1, true)", &[&graph]);
            if let Err(e) = r {
                std::panic::resume_unwind(e);
            }
        });
    }

    fn sid(v: &[skmem::pg::graph_arm::Stub]) -> Vec<String> {
        ids(v.iter().filter_map(|s| s.id.clone()))
    }

    #[test]
    fn graph_arm_hides_ids_on_every_lookup_path() {
        let Some(dsn) = test_dsn() else { return };
        with_graph(&dsn, |arm| {
            let p = public();
            let o = owner();
            let f = Filters::default();
            // entity search (all three entry points)
            let hits = |a: &mut GraphArm, sc: &ReaderScope| {
                ids(a
                    .search_by_entity("Zed", 50, &f, sc)
                    .unwrap()
                    .into_iter()
                    .filter_map(|h| h.id))
            };
            assert_eq!(hits(arm, &o), ["g1", "g2", "g3", "g4", "g5"]);
            assert_eq!(hits(arm, &p), ["g1", "g2", "g4"]);
            let tok = ids(arm
                .search_by_entity_tokens("Zed", 50, &f, &p)
                .unwrap()
                .into_iter()
                .filter_map(|h| h.id));
            assert_eq!(tok, ["g1", "g2", "g4"]);
            let out = arm.search("Zed", 50, &f, &p).unwrap();
            assert!(out.hits.iter().all(|h| h.id.as_deref() != Some("g3")));
            // widening through the per-call reader
            let widened = scope(Some("owner"), Some("@public"));
            assert_eq!(hits(arm, &widened), ["g1", "g2", "g4"]);

            // currently valid
            let cv = arm
                .currently_valid_memories(Some("2026-11-01T00:00:00+00:00"), 50, &p)
                .unwrap();
            assert!(!sid(&cv).contains(&"g3".to_string()) && !sid(&cv).contains(&"g5".to_string()));
            // is_currently_valid: a hidden id is `false`, exactly like a missing one
            let t = Some("2026-11-01T00:00:00+00:00");
            assert!(!arm.is_currently_valid("g3", t, &p).unwrap());
            assert_eq!(
                arm.is_currently_valid("g3", t, &p).unwrap(),
                arm.is_currently_valid("nope", t, &p).unwrap()
            );
            assert!(arm.is_currently_valid("g3", t, &o).unwrap());
            // bad as_of is still an error for a hidden id (same as for a visible one)
            assert!(arm.is_currently_valid("g3", Some("garbage"), &p).is_err());

            // neighbours: a hidden start is EMPTY like a missing one, hidden neighbours dropped
            assert_eq!(arm.neighbors("g3", t, &p).unwrap().len(), 0);
            assert_eq!(arm.neighbors("nope", t, &p).unwrap().len(), 0);
            assert_eq!(sid(&arm.neighbors("g2", t, &p).unwrap()), ["g1"]);
            assert!(sid(&arm.neighbors("g2", t, &o).unwrap()).contains(&"g3".to_string()));
            assert_eq!(sid(&arm.neighbors("g1", t, &p).unwrap()), ["g2"]);

            // supersedes chain: cut at the hidden g3, nothing beyond it
            assert!(arm.supersedes_chain("g3", t, &p).unwrap().is_empty());
            assert_eq!(sid(&arm.supersedes_chain("g2", t, &p).unwrap()), ["g1"]);
            assert_eq!(
                sid(&arm.supersedes_chain("g4", t, &p).unwrap()),
                Vec::<String>::new()
            );
            assert_eq!(
                sid(&arm.supersedes_chain("g4", t, &o).unwrap()),
                ["g1", "g2", "g3"]
            );

            // related: never walks through a hidden node
            assert!(arm.get_related("g3", 5, &p).unwrap().is_empty());
            let rel = sid(&arm.get_related("g2", 5, &p).unwrap());
            assert_eq!(rel, ["g1"]);
            assert!(!rel.contains(&"g3".to_string()) && !rel.contains(&"g4".to_string()));
            assert!(sid(&arm.get_related("g2", 5, &o).unwrap()).contains(&"g3".to_string()));

            // lineage: hidden start is empty, chain is cut at the first hidden ancestor
            assert!(arm.get_lineage("g3", &p).unwrap().is_empty());
            assert!(arm.get_lineage("nope", &p).unwrap().is_empty());
            let lin = sid(&arm.get_lineage("g4", &p).unwrap());
            assert!(
                lin.is_empty(),
                "g3 (hidden) is the first ancestor of g4: {lin:?}"
            );
            assert_eq!(sid(&arm.get_lineage("g2", &p).unwrap()), ["g1"]);
            assert_eq!(sid(&arm.get_lineage("g4", &o).unwrap()), ["g1", "g2", "g3"]);

            // an id with no memories row has an unknowable audience: hidden (fail closed)
            arm.cypher(
                "CREATE (m:Memory {id: 'orphan', title: 'orphan', layer: 'short-term'}) \
                 MERGE (e:Entity {name: 'Zed'}) CREATE (m)-[:MENTIONS]->(e) RETURN m",
                &json!({}),
                1,
                None,
            )
            .unwrap();
            assert!(!hits(arm, &p).contains(&"orphan".to_string()));
            assert!(hits(arm, &o).contains(&"orphan".to_string()));
        });
    }
}
